{
  "root": "main_stack",
  "state": {
    "itineraryRows": [
      {
        "dayTitle": "Day 1: Arashiyama Scenic Beauty",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Arashiyama_Bamboo_Grove_Kyoto.jpg/1200px-Arashiyama_Bamboo_Grove_Kyoto.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/tree.svg",
        "morningActivity": "Arashiyama Bamboo Grove and Tenryu-ji Temple (Autumn colors). Cost: 800 JPY/adult.",
        "afternoonActivity": "Iwatayama Monkey Park for interactive fun. Cost: 600 JPY/adult.",
        "vegetarianRecommendation": "Shigetsu (inside Tenryu-ji) – Authentic Shojin Ryori with no dashi.",
        "actionLabel": "Shigetsu Booking",
        "actionUrl": "https://www.tenryuji.com/en/shigetsu/"
      },
      {
        "dayTitle": "Day 2: Golden Pavilion & Gion Traditions",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Kinkakuji_2023.jpg/1200px-Kinkakuji_2023.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/building.svg",
        "morningActivity": "Kinkaku-ji (Golden Pavilion) for stunning foliage reflections. Cost: 500 JPY/adult.",
        "afternoonActivity": "Kyoto International Manga Museum for kids. Cost: 900 JPY/adult.",
        "vegetarianRecommendation": "Gion Veggie – Specializes in meat-free traditional sets in Gion.",
        "actionLabel": "Manga Museum Info",
        "actionUrl": "https://www.kyotomm.jp/en/"
      },
      {
        "dayTitle": "Day 3: Fushimi Inari & Kyoto Station Tech",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Fushimi_Inari_Taisha_Senbon_Torii.jpg/1200px-Fushimi_Inari_Taisha_Senbon_Torii.jpg",
        "icon": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/geo-alt.svg",
        "morningActivity": "Fushimi Inari Shrine (Torii gates). Cost: Free.",
        "afternoonActivity": "Kyoto Railway Museum for interactive exhibits. Cost: 1,500 JPY/adult.",
        "vegetarianRecommendation": "Ain Soph. Journey Kyoto – Famous for vegan pancakes and savory dishes.",
        "actionLabel": "Railway Museum",
        "actionUrl": "https://www.kyotorailwaymuseum.jp/en/"
      }
    ],
    "budgetRows": [
      {
        "Category": "Entrance Fees",
        "Day 1": "$45",
        "Day 2": "$50",
        "Day 3": "$60"
      },
      {
        "Category": "Dining (4 people)",
        "Day 1": "$320",
        "Day 2": "$300",
        "Day 3": "$280"
      },
      {
        "Category": "Local Transport",
        "Day 1": "$35",
        "Day 2": "$35",
        "Day 3": "$30"
      },
      {
        "Category": "Total",
        "Day 1": "$400",
        "Day 2": "$385",
        "Day 3": "$370"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "overview_h2",
        "overview_body",
        "itinerary_h2",
        "itinerary_table",
        "budget_h2",
        "budget_table",
        "quick_actions_h3",
        "bus_pass_button",
        "vegetarian_guide_button",
        "sources_h3",
        "kyoto_tourism_button",
        "japan_tourism_button"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Kyoto Family Autumn Journey",
        "variant": "h1"
      },
      "children": []
    },
    "overview_h2": {
      "type": "Text",
      "props": {
        "text": "Trip Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_body": {
      "type": "Text",
      "props": {
        "text": "This 3-day itinerary is optimized for a family of four staying near Kyoto Station, focusing on autumn colors and vegetarian-friendly dining (no fish stock/dashi) within a $500/day budget."
      },
      "children": []
    },
    "itinerary_h2": {
      "type": "Text",
      "props": {
        "text": "Daily Itinerary Breakdown",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "dayTitle",
        "highlightColumns": [
          "morningActivity",
          "afternoonActivity"
        ],
        "statePath": "/itineraryRows",
        "columns": [
          {
            "key": "dayTitle",
            "label": "Day"
          },
          {
            "key": "image",
            "label": "Image"
          },
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "morningActivity",
            "label": "Morning"
          },
          {
            "key": "afternoonActivity",
            "label": "Afternoon"
          },
          {
            "key": "vegetarianRecommendation",
            "label": "Vegetarian Dining"
          },
          {
            "key": "actionLabel",
            "label": "Action"
          },
          {
            "key": "actionUrl",
            "label": "Action URL"
          }
        ]
      },
      "children": []
    },
    "budget_h2": {
      "type": "Text",
      "props": {
        "text": "Daily Budget Breakdown (USD)",
        "variant": "h2"
      },
      "children": []
    },
    "budget_table": {
      "type": "Table",
      "props": {
        "domain": "generic",
        "preferredPresentation": "table",
        "statePath": "/budgetRows",
        "columns": [
          {
            "key": "Category",
            "label": "Category"
          },
          {
            "key": "Day 1",
            "label": "Day 1"
          },
          {
            "key": "Day 2",
            "label": "Day 2"
          },
          {
            "key": "Day 3",
            "label": "Day 3"
          }
        ]
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "bus_pass_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto Bus Pass"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.city.kyoto.lg.jp/kotsu/page/0000028337.html"
          }
        }
      },
      "children": []
    },
    "vegetarian_guide_button": {
      "type": "Button",
      "props": {
        "label": "Vegetarian Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.happycow.net/asia/japan/kyoto/"
          }
        }
      },
      "children": []
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "kyoto_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Kyoto City Tourism",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://kyoto.travel/en/"
          }
        }
      },
      "children": []
    },
    "japan_tourism_button": {
      "type": "Button",
      "props": {
        "label": "Japan National Tourism",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.japan.travel/en/"
          }
        }
      },
      "children": []
    }
  }
}
